/* eslint-disable @typescript-eslint/no-unused-expressions */

import LineChart = require( './index' );


// TESTS //

// The constructor returns a line chart instance...
{
	new LineChart(); // $ExpectType LineChart
	new LineChart( [ 4, 5, 6 ] ); // $ExpectType LineChart
	new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ] ); // $ExpectType LineChart
	new LineChart( [ 1, 2, 3 ], [ [ 4, 5, 6 ], [ 7, 8, 9 ] ] ); // $ExpectType LineChart
	new LineChart( {} ); // $ExpectType LineChart
	new LineChart( { 'legend': true } ); // $ExpectType LineChart
	new LineChart( [ 4, 5, 6 ], { 'lineStyle': '--' } ); // $ExpectType LineChart
	new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ], { 'lineWidth': [ 2, 4 ] } ); // $ExpectType LineChart
}

// The compiler throws an error if the constructor is provided an invalid first argument...
{
	new LineChart( 5 ); // $ExpectError
	new LineChart( true ); // $ExpectError
	new LineChart( false ); // $ExpectError
	new LineChart( null ); // $ExpectError
	new LineChart( ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the constructor is provided an invalid second argument...
{
	new LineChart( [ 1, 2, 3 ], 5 ); // $ExpectError
	new LineChart( [ 1, 2, 3 ], true ); // $ExpectError
	new LineChart( [ 1, 2, 3 ], false ); // $ExpectError
	new LineChart( [ 1, 2, 3 ], null ); // $ExpectError
	new LineChart( [ 1, 2, 3 ], ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the constructor is provided an invalid third argument...
{
	new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ], 5 ); // $ExpectError
	new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ], true ); // $ExpectError
	new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ], false ); // $ExpectError
	new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ], null ); // $ExpectError
	new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ], 'abc' ); // $ExpectError
	new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ], [] ); // $ExpectError
	new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ], ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the constructor is provided a `colors` option which is not a string or an array of strings...
{
	new LineChart( { 'colors': 5 } ); // $ExpectError
	new LineChart( { 'colors': true } ); // $ExpectError
	new LineChart( { 'colors': null } ); // $ExpectError
	new LineChart( { 'colors': [ 5 ] } ); // $ExpectError
	new LineChart( { 'colors': {} } ); // $ExpectError
}

// The compiler throws an error if the constructor is provided a `legend` option which is not a boolean...
{
	new LineChart( { 'legend': 5 } ); // $ExpectError
	new LineChart( { 'legend': 'abc' } ); // $ExpectError
	new LineChart( { 'legend': null } ); // $ExpectError
	new LineChart( { 'legend': [] } ); // $ExpectError
	new LineChart( { 'legend': {} } ); // $ExpectError
}

// The compiler throws an error if the constructor is provided a `lineOpacity` option which is not a number or an array of numbers...
{
	new LineChart( { 'lineOpacity': 'abc' } ); // $ExpectError
	new LineChart( { 'lineOpacity': true } ); // $ExpectError
	new LineChart( { 'lineOpacity': null } ); // $ExpectError
	new LineChart( { 'lineOpacity': [ 'abc' ] } ); // $ExpectError
	new LineChart( { 'lineOpacity': {} } ); // $ExpectError
}

// The compiler throws an error if the constructor is provided a `lineStyle` option which is not a line style or an array of line styles...
{
	new LineChart( { 'lineStyle': 5 } ); // $ExpectError
	new LineChart( { 'lineStyle': 'abc' } ); // $ExpectError
	new LineChart( { 'lineStyle': true } ); // $ExpectError
	new LineChart( { 'lineStyle': null } ); // $ExpectError
	new LineChart( { 'lineStyle': [ 'abc' ] } ); // $ExpectError
	new LineChart( { 'lineStyle': {} } ); // $ExpectError
}

// The compiler throws an error if the constructor is provided a `lineSymbol` option which is not a string or an array of strings...
{
	new LineChart( { 'lineSymbol': 5 } ); // $ExpectError
	new LineChart( { 'lineSymbol': true } ); // $ExpectError
	new LineChart( { 'lineSymbol': null } ); // $ExpectError
	new LineChart( { 'lineSymbol': [ 5 ] } ); // $ExpectError
	new LineChart( { 'lineSymbol': {} } ); // $ExpectError
}

// The compiler throws an error if the constructor is provided a `lineWidth` option which is not a number or an array of numbers...
{
	new LineChart( { 'lineWidth': 'abc' } ); // $ExpectError
	new LineChart( { 'lineWidth': true } ); // $ExpectError
	new LineChart( { 'lineWidth': null } ); // $ExpectError
	new LineChart( { 'lineWidth': [ 'abc' ] } ); // $ExpectError
	new LineChart( { 'lineWidth': {} } ); // $ExpectError
}

// The compiler throws an error if the constructor is provided more than three arguments...
{
	new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ], {}, {} ); // $ExpectError
}

// An instance has writable line properties...
{
	const chart = new LineChart();

	chart.colors = 'red'; // $ExpectType "red"
	chart.colors = [ 'red', 'blue' ]; // $ExpectType string[]
	chart.legend = true; // $ExpectType true
	chart.lineOpacity = 0.5; // $ExpectType 0.5
	chart.lineOpacity = [ 1.0, 0.5 ]; // $ExpectType number[]
	chart.lineStyle = '--'; // $ExpectType "--"
	chart.lineStyle = [ '-', ':' ]; // $ExpectType ("-" | ":")[]
	chart.lineSymbol = 'circle'; // $ExpectType "circle"
	chart.lineSymbol = [ 'stroke', 'circle' ]; // $ExpectType string[]
	chart.lineWidth = 4; // $ExpectType 4
	chart.lineWidth = [ 2, 4 ]; // $ExpectType number[]
}

// The compiler throws an error if a writable line property is assigned an invalid value...
{
	const chart = new LineChart();

	chart.colors = 5; // $ExpectError
	chart.legend = 'abc'; // $ExpectError
	chart.lineOpacity = 'abc'; // $ExpectError
	chart.lineStyle = 'abc'; // $ExpectError
	chart.lineSymbol = 5; // $ExpectError
	chart.lineWidth = 'abc'; // $ExpectError
}

// An instance has read-only scale properties...
{
	const chart = new LineChart();

	chart.colorScale; // $ExpectType OrdinalScale
	chart.lineOpacityScale; // $ExpectType OrdinalScale
	chart.lineStyleScale; // $ExpectType OrdinalScale
	chart.lineSymbolScale; // $ExpectType OrdinalScale
	chart.lineWidthScale; // $ExpectType OrdinalScale
}

// The `render` method returns `undefined`...
{
	/**
	* Callback invoked upon rendering a chart.
	*
	* @param error - error object
	* @param svg - rendered SVG string
	*/
	function onRender( error: Error | null, svg?: string ): void {
		if ( error || svg ) {
			return;
		}
	}

	const chart = new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ] );

	chart.render( onRender ); // $ExpectType void
}

// The compiler throws an error if the `render` method is provided an invalid argument...
{
	const chart = new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ] );

	chart.render(); // $ExpectError
	chart.render( 5 ); // $ExpectError
	chart.render( 'abc' ); // $ExpectError
	chart.render( null ); // $ExpectError
	chart.render( {} ); // $ExpectError
}

// The `toJSON` method returns a JSON object...
{
	const chart = new LineChart( [ 1, 2, 3 ], [ 4, 5, 6 ] );

	chart.toJSON(); // $ExpectType any
}

// The compiler throws an error if the `toJSON` method is provided any arguments...
{
	const chart = new LineChart();

	chart.toJSON( {} ); // $ExpectError
}
